  "code": "export default async function ({ page }) {
  const cookies = {{ JSON.stringify($json.session.cookies) }};
  const targetUrl = '{{ $json.session.url }}';

  await page.setViewport({ width: 1280, height: 900 });

  if (cookies && cookies.length > 0) {
    await page.setCookie(...cookies);
  }

  await page.goto(targetUrl, { waitUntil: 'networkidle2', timeout: 30000 });
  await new Promise(r => setTimeout(r, 2000));

  const screenshot = await page.screenshot({ encoding: 'base64', fullPage: false });

  const clickables = await page.$$eval('a, button, input, select, [onclick], [role="button"], div[class*="click"], span[class*="button"]', els => els.map((el, index) => {
    const rect = el.getBoundingClientRect();
    const style = window.getComputedStyle(el);
    return {
      i: index,
      tag: el.tagName,
      text: (el.textContent || '').trim().substring(0, 80),
      type: el.type || null,
      placeholder: el.placeholder || null,
      value: el.value || null,
      x: Math.round(rect.x + rect.width/2),
      y: Math.round(rect.y + rect.height/2),
      w: Math.round(rect.width),
      h: Math.round(rect.height),
      vis: rect.width > 0 && rect.height > 0 && rect.y >= 0 && rect.y < 900 && style.visibility !== 'hidden' && style.display !== 'none'
    };
  }).filter(el => el.vis));

  return {
    url: page.url(),
    screenshot: screenshot,
    elementos: clickables.slice(0, 50),
    cookies: await page.cookies()
  };
}"
}

