const captura = $('2. Captura Tela').first().json;
const iaResponse = $input.first().json;
const loopData = $('Init Loop').first().json;

let iaDecisao;
try {
  let content = iaResponse.choices[0].message.content;
  // Limpar markdown
  if (content.includes('```')) {
    content = content.replace(/```json?\n?/g, '').replace(/```/g, '');
  }
  iaDecisao = JSON.parse(content.trim());
} catch (e) {
  iaDecisao = { acao: 'erro', motivo: 'Falha parse: ' + (iaResponse.choices?.[0]?.message?.content || 'sem resposta') };
}

// Adicionar ao historico
const historico = loopData.historico || [];
historico.push({
  iteracao: loopData.iteracao,
  acao: iaDecisao.acao,
  index: iaDecisao.index,
  etapa: iaDecisao.etapa,
  motivo: iaDecisao.motivo
});

return [{
  json: {
    ...iaDecisao,
    url: captura.url,
    cookies: captura.cookies,
    elementos: captura.elementos,
    iteracao: loopData.iteracao,
    historico: historico
  }
}];

