  "code": "export default async function ({ page }) {
    const cookies = {{ JSON.stringify($json.cookies) }};
    const targetUrl = '{{ $json.url }}';
    const elementIndex = {{ $json.index || 0 }};
    const elementos = {{ JSON.stringify($json.elementos) }};
    const valorDigitar = '{{ $json.valor || '' }}';

    await page.setViewport({ width: 1280, height: 900 });

    if (cookies && cookies.length > 0) {
      await page.setCookie(...cookies);
    }

    await page.goto(targetUrl, { waitUntil: 'networkidle2', timeout: 30000 });
    await new Promise(r => setTimeout(r, 2000));

    const el = elementos.find(e => e.i === elementIndex);
    let resultado = 'nao encontrado';

    if (el) {
      await page.mouse.click(el.x, el.y);
      await new Promise(r => setTimeout(r, 500));

      // Limpar campo e digitar
