      await page.keyboard.press('a');
      await page.keyboard.up('Control');
      await page.keyboard.type(valorDigitar, { delay: 30 });

      resultado = 'digitou: ' + valorDigitar;
      await new Promise(r => setTimeout(r, 1000));
    }

    return {
      success: true,
      acao: 'digitou',
      resultado: resultado,
      url: page.url(),
      cookies: await page.cookies()
    };
  }"
}

